From fd21aa04ef4159300272097aa4342e477a3776c7 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:09:38 +0100
Subject: [PATCH] applets/taskmanager: replace "Do not sort" with locking
 manual positions

"Do not sort" and "Manually" looked like the same thing but one let you
drag tasks and the other kept them in a fixed order you couldn't choose.
Drop "Do not sort" and add a "Lock positions" option for manual sorting.

BUG: 502465
---
 applets/taskmanager/main.xml               |  4 ++++
 applets/taskmanager/qml/ConfigBehavior.qml | 11 +++++++----
 applets/taskmanager/qml/MouseHandler.qml   |  4 ++++
 applets/taskmanager/qml/main.qml           | 13 +++++++++++++
 4 files changed, 28 insertions(+), 4 deletions(-)

diff --git a/applets/taskmanager/main.xml b/applets/taskmanager/main.xml
index 8c3b68785b..08f866564f 100644
--- a/applets/taskmanager/main.xml
+++ b/applets/taskmanager/main.xml
@@ -54,6 +54,10 @@
       <label>Values from TaskManager::TasksModel::SortMode</label>
       <default>1</default>
     </entry>
+    <entry name="lockTaskPositions" type="Bool">
+      <label>Whether manually sorted tasks are kept from being rearranged.</label>
+      <default>false</default>
+    </entry>
     <entry name="separateLaunchers" type="Bool">
       <label>Whether launcher tasks are sorted separately at the left side of the widget or can be mixed with other tasks.</label>
       <default>true</default>
diff --git a/applets/taskmanager/qml/ConfigBehavior.qml b/applets/taskmanager/qml/ConfigBehavior.qml
index bd4b7cf008..92ecce6e62 100644
--- a/applets/taskmanager/qml/ConfigBehavior.qml
+++ b/applets/taskmanager/qml/ConfigBehavior.qml
@@ -24,6 +24,7 @@ KCMUtils.SimpleKCM {
     property alias cfg_groupPopups: groupPopups.checked
     property alias cfg_onlyGroupWhenFull: onlyGroupWhenFull.checked
     property int cfg_sortingStrategy
+    property alias cfg_lockTaskPositions: lockTaskPositions.checked
     property alias cfg_separateLaunchers: separateLaunchers.checked
     property alias cfg_hideLauncherOnStart: hideLauncherOnStart.checked
     property alias cfg_middleClickAction: middleClickAction.currentIndex
@@ -130,10 +131,6 @@ KCMUtils.SimpleKCM {
             textRole: "text"
             valueRole: "value"
             model: [
-                {
-                    "text": i18nc("@item:inlistbox sort tasks in grouped task", "Do not sort"),
-                    "value": TaskManager.TasksModel.SortDisabled,
-                },
                 {
                     "text": i18nc("@item:inlistbox sort tasks in grouped task", "Manually"),
                     "value": TaskManager.TasksModel.SortManual,
@@ -159,6 +156,12 @@ KCMUtils.SimpleKCM {
             Component.onCompleted: currentIndex = indexOfValue(root.cfg_sortingStrategy)
         }

+        QQC2.CheckBox {
+            id: lockTaskPositions
+            text: i18nc("@option:check configure task sorting", "Lock positions")
+            enabled: sortingStrategy.currentValue === TaskManager.TasksModel.SortManual
+        }
+
         QQC2.CheckBox {
             id: separateLaunchers
             visible: (Plasmoid.pluginName !== "org.kde.plasma.icontasks")
diff --git a/applets/taskmanager/qml/MouseHandler.qml b/applets/taskmanager/qml/MouseHandler.qml
index 2fd85860c2..b3542dd112 100644
--- a/applets/taskmanager/qml/MouseHandler.qml
+++ b/applets/taskmanager/qml/MouseHandler.qml
@@ -75,6 +75,10 @@ DropArea {
         }

         if (tasksModel.sortMode === TaskManager.TasksModel.SortManual && tasks.dragSource) {
+            if (tasks.taskPositionsLocked) {
+                return;
+            }
+
             // Reject drags between different TaskList instances.
             if (tasks.dragSource.parent !== above.parent) {
                 return;
diff --git a/applets/taskmanager/qml/main.qml b/applets/taskmanager/qml/main.qml
index d0a62d21bc..f522af36e3 100644
--- a/applets/taskmanager/qml/main.qml
+++ b/applets/taskmanager/qml/main.qml
@@ -87,6 +87,9 @@ PlasmoidItem {
     }
 //END TODO

+    readonly property bool taskPositionsLocked: Plasmoid.configuration.sortingStrategy === 1
+        && Plasmoid.configuration.lockTaskPositions
+
     property Item dragSource
     property var hoveredWinIds

@@ -228,6 +231,12 @@ PlasmoidItem {
         }

         Component.onCompleted: {
+            // "Do not sort" was replaced by manual sorting with locked positions.
+            if (Plasmoid.configuration.sortingStrategy === 0) {
+                Plasmoid.configuration.sortingStrategy = 1;
+                Plasmoid.configuration.lockTaskPositions = true;
+            }
+
             launcherList = Plasmoid.configuration.launchers;
             groupingAppIdBlacklist = Plasmoid.configuration.groupingAppIdBlacklist;
             groupingLauncherUrlBlacklist = Plasmoid.configuration.groupingLauncherUrlBlacklist;
@@ -640,6 +649,8 @@ PlasmoidItem {
     }

     function moveActiveTaskBackward(): void {
+        if (tasks.taskPositionsLocked) return;
+
         const activeRow = getActiveRow();
         if (activeRow <= 0) return; // Already leftmost

@@ -647,6 +658,8 @@ PlasmoidItem {
     }

     function moveActiveTaskForward(): void {
+        if (tasks.taskPositionsLocked) return;
+
         const activeRow = getActiveRow();
         if (activeRow < 0 || activeRow >= tasksModel.count - 1) return; // Already rightmost

-- 
2.53.0
